from flask import Flask, request, jsonify
from sqlalchemy import create_engine, text
import os

app = Flask(__name__)

# Database connection using environment-provided credentials
DATABASE_URL = os.environ.get('DATABASE_URL', 'postgresql://appuser:password@db:5432/myapp')
engine = create_engine(DATABASE_URL)

class User:
    ALLOWED_FIELDS = ['username', 'email', 'display_name']
    ADMIN_FIELDS = ['role', 'is_admin', 'permissions', 'account_tier']

    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            setattr(self, key, value)

@app.route('/api/users/<int:user_id>', methods=['PATCH'])
def update_user(user_id):
    """Update user profile - supports partial updates"""
    auth_token = request.headers.get('Authorization')
    if not auth_token:
        return jsonify({'error': 'Unauthorized'}), 401

    # Get requesting user from token (simplified)
    requesting_user_id = validate_token(auth_token)
    if requesting_user_id is None:
        return jsonify({'error': 'Invalid token'}), 401

    data = request.get_json()
    if not data:
        return jsonify({'error': 'No data provided'}), 400

    # VULNERABILITY: No field filtering - accepts any field from request body
    # An attacker can set 'role', 'is_admin', 'permissions', etc.
    set_clauses = []
    params = {'user_id': user_id}

    for field, value in data.items():
        # Basic SQL injection prevention via parameterized queries
        # but NO mass assignment protection
        sanitized_field = ''.join(c for c in field if c.isalnum() or c == '_')
        if sanitized_field and len(sanitized_field) < 64:
            set_clauses.append(f"{sanitized_field} = :val_{sanitized_field}")
            params[f'val_{sanitized_field}'] = value

    if not set_clauses:
        return jsonify({'error': 'No valid fields'}), 400

    # Only allow users to update their own profile (unless admin)
    if requesting_user_id != user_id:
        with engine.connect() as conn:
            result = conn.execute(
                text("SELECT is_admin FROM users WHERE id = :uid"),
                {'uid': requesting_user_id}
            )
            row = result.fetchone()
            if not row or not row[0]:
                return jsonify({'error': 'Forbidden'}), 403

    query = f"UPDATE users SET {', '.join(set_clauses)} WHERE id = :user_id"

    try:
        with engine.connect() as conn:
            conn.execute(text(query), params)
            conn.commit()
        return jsonify({'status': 'updated', 'fields': list(data.keys())})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile"""
    with engine.connect() as conn:
        result = conn.execute(
            text("SELECT id, username, email, display_name, role, is_admin, account_tier FROM users WHERE id = :uid"),
            {'uid': user_id}
        )
        row = result.fetchone()
        if not row:
            return jsonify({'error': 'Not found'}), 404
        return jsonify({
            'id': row[0], 'username': row[1], 'email': row[2],
            'display_name': row[3], 'role': row[4], 'is_admin': row[5],
            'account_tier': row[6]
        })

def validate_token(token):
    """Simplified token validation"""
    try:
        # In production this would verify JWT
        parts = token.replace('Bearer ', '').split('.')
        import base64, json
        payload = json.loads(base64.b64decode(parts[1] + '=='))
        return payload.get('user_id')
    except:
        return None

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
